#!/usr/bin/env python3
"""
Improved Supply Chain Fulfillment Solver with backtracking.
"""

import json
from collections import defaultdict
from pathlib import Path

def load_data(input_dir):
    """Load all input data files."""
    shipments = {}
    with open(input_dir / "shipments.jsonl") as f:
        for line in f:
            if line.strip():
                s = json.loads(line)
                shipments[s["shipment_id"]] = s

    warehouses = {}
    with open(input_dir / "warehouses.jsonl") as f:
        for line in f:
            if line.strip():
                w = json.loads(line)
                warehouses[w["warehouse_id"]] = w

    destinations = {}
    with open(input_dir / "destinations.jsonl") as f:
        for line in f:
            if line.strip():
                d = json.loads(line)
                destinations[d["destination_id"]] = d

    routes = {}
    routes_by_wh = defaultdict(list)
    routes_by_wh_dest = {}
    with open(input_dir / "routes.jsonl") as f:
        for line in f:
            if line.strip():
                r = json.loads(line)
                routes[r["route_id"]] = r
                routes_by_wh[r["warehouse_id"]].append(r)
                routes_by_wh_dest[(r["warehouse_id"], r["destination_id"])] = r

    compatibility = []
    with open(input_dir / "compatibility.jsonl") as f:
        for line in f:
            if line.strip():
                compatibility.append(json.loads(line))

    return shipments, warehouses, destinations, routes, routes_by_wh, routes_by_wh_dest, compatibility

def get_valid_warehouses_for_shipment(shipment, warehouses, routes_by_wh_dest, destinations, 
                                       wh_volume_used, wh_weight_used, route_volume_used, route_weight_used,
                                       wh_has_hazmat, wh_has_refrigerated):
    """Get all warehouses that can serve a shipment, checking current capacities."""
    valid_wh = []
    dest_id = shipment["destination_id"]
    deadline = shipment["deadline_hours"]
    requires_hazmat = shipment["requires_hazmat"]
    requires_refrigerated = shipment["requires_refrigerated"]
    requires_oversized = shipment["requires_oversized"]
    volume = shipment["volume"]
    weight = shipment["weight"]

    dest = destinations.get(dest_id)
    if not dest:
        return []

    window_start = dest["delivery_window_start"]
    window_end = dest["delivery_window_end"]

    for wh_id, wh in warehouses.items():
        # Check warehouse capability constraints
        if requires_hazmat and not wh["handles_hazmat"]:
            continue
        if requires_refrigerated and not wh["handles_refrigerated"]:
            continue
        if requires_oversized and not wh["handles_oversized"]:
            continue

        # Check route exists
        route = routes_by_wh_dest.get((wh_id, dest_id))
        if not route:
            continue

        # Check route capability constraints
        if requires_hazmat and not route["allows_hazmat"]:
            continue
        if requires_refrigerated and not route["allows_refrigerated"]:
            continue
        if requires_oversized and not route["allows_oversized"]:
            continue

        # Calculate arrival time
        arrival_time = wh["availability_start"] + route["transit_time_hours"]

        # Check deadline constraint
        if arrival_time > deadline:
            continue

        # Check delivery window constraint
        if arrival_time < window_start or arrival_time > window_end:
            continue

        # Check warehouse capacity
        if wh_volume_used[wh_id] + volume > wh["volume_capacity"]:
            continue
        if wh_weight_used[wh_id] + weight > wh["weight_capacity"]:
            continue

        # Check route capacity
        route_key = (wh_id, dest_id)
        if route_volume_used[route_key] + volume > route["capacity_volume"]:
            continue
        if route_weight_used[route_key] + weight > route["capacity_weight"]:
            continue

        # Constraint 13: No hazmat + refrigerated mix
        if requires_hazmat and wh_has_hazmat[wh_id] and requires_refrigerated:
            continue
        if requires_refrigerated and wh_has_refrigerated[wh_id] and requires_hazmat:
            continue

        valid_wh.append({
            "warehouse_id": wh_id,
            "warehouse": wh,
            "route": route,
            "arrival_time": arrival_time,
            "cost": (wh["base_handling_cost"] * (volume / 100) + 
                   route["base_cost_per_km"] * route["distance_km"] * (weight / 1000)) * shipment["priority_multiplier"]
        })

    return valid_wh

def solve_with_backtracking(shipments, warehouses, destinations, routes_by_wh_dest, compatibility):
    """Solve using backtracking with MRV heuristic."""

    # Precompute static valid warehouses (ignoring dynamic capacity)
    shipment_static_options = {}
    for sid, s in shipments.items():
        opts = get_valid_warehouses_for_shipment(s, warehouses, routes_by_wh_dest, destinations,
                                                 defaultdict(int), defaultdict(int), defaultdict(int), defaultdict(int),
                                                 defaultdict(bool), defaultdict(bool))
        shipment_static_options[sid] = opts

    # Get number of options per shipment - for MRV ordering
    num_options = {sid: len(opts) for sid, opts in shipment_static_options.items()}

    # Sort shipments by number of options (MRV - most constrained first)
    # Tie-break by deadline urgency
    shipments_list = list(shipments.items())

    # Compute deadline urgency: how much slack we have
    # urgency = deadline - min_possible_arrival
    shipments_sorted = []
    for sid, s in shipments_list:
        min_arrival = float('inf')
        for opt in shipment_static_options.get(sid, []):
            min_arrival = min(min_arrival, opt["arrival_time"])
        urgency = s["deadline_hours"] - min_arrival if min_arrival != float('inf') else float('inf')
        shipments_sorted.append((sid, s, num_options[sid], urgency))

    # Sort by: fewest options first, then tightest deadline (smallest urgency)
    shipments_sorted.sort(key=lambda x: (x[2], x[3]))
    shipment_order = [x[0] for x in shipments_sorted]

    # State tracking
    wh_volume_used = defaultdict(int)
    wh_weight_used = defaultdict(int)
    route_volume_used = defaultdict(int)
    route_weight_used = defaultdict(int)
    wh_has_hazmat = defaultdict(bool)
    wh_has_refrigerated = defaultdict(bool)
    assignments = {}  # shipment_id -> (warehouse_id, destination_id)

    def is_valid_assignment(sid, wh_id, s):
        """Check if assigning shipment sid to warehouse wh_id is valid."""
        dest_id = s["destination_id"]
        volume = s["volume"]
        weight = s["weight"]
        requires_hazmat = s["requires_hazmat"]
        requires_refrigerated = s["requires_refrigerated"]
        requires_oversized = s["requires_oversized"]

        wh = warehouses[wh_id]
        route = routes_by_wh_dest.get((wh_id, dest_id))
        if not route:
            return False

        # Check route capabilities
        if requires_hazmat and not route["allows_hazmat"]:
            return False
        if requires_refrigerated and not route["allows_refrigerated"]:
            return False
        if requires_oversized and not route["allows_oversized"]:
            return False

        # Check warehouse capabilities
        if requires_hazmat and not wh["handles_hazmat"]:
            return False
        if requires_refrigerated and not wh["handles_refrigerated"]:
            return False
        if requires_oversized and not wh["handles_oversized"]:
            return False

        arrival_time = wh["availability_start"] + route["transit_time_hours"]
        if arrival_time > s["deadline_hours"]:
            return False
        dest = destinations[dest_id]
        if arrival_time < dest["delivery_window_start"] or arrival_time > dest["delivery_window_end"]:
            return False

        # Check capacities
        if wh_volume_used[wh_id] + volume > wh["volume_capacity"]:
            return False
        if wh_weight_used[wh_id] + weight > wh["weight_capacity"]:
            return False

        route_key = (wh_id, dest_id)
        if route_volume_used[route_key] + volume > route["capacity_volume"]:
            return False
        if route_weight_used[route_key] + weight > route["capacity_weight"]:
            return False

        # Constraint 13: No hazmat + refrigerated mix
        if requires_hazmat and wh_has_hazmat[wh_id] and requires_refrigerated:
            return False
        if requires_refrigerated and wh_has_refrigerated[wh_id] and requires_hazmat:
            return False

        return True

    def assign_shipment(sid, wh_id, s):
        """Recursively assign a shipment to a warehouse."""
        assignments[sid] = (wh_id, s["destination_id"])
        wh_volume_used[wh_id] += s["volume"]
        wh_weight_used[wh_id] += s["weight"]
        route_key = (wh_id, s["destination_id"])
        route_volume_used[route_key] += s["volume"]
        route_weight_used[route_key] += s["weight"]
        if s["requires_hazmat"]:
            wh_has_hazmat[wh_id] = True
        if s["requires_refrigerated"]:
            wh_has_refrigerated[wh_id] = True

        # Try next shipment
        next_sid = shipment_order[shipment_order.index(sid) + 1] if shipment_order.index(sid) + 1 < len(shipment_order) else None
        if next_sid is None:
            return True  # All shipments assigned

        # Find next unassigned shipment
        for candidate_sid in shipment_order[shipment_order.index(sid) + 1:]:
            if candidate_sid not in assignments:
                next_sid = candidate_sid
                break

        if next_sid is None:
            return True

        s_next = shipments[next_sid]
        for opt in shipment_static_options.get(next_sid, []):
            wh_id = opt["warehouse_id"]
            if is_valid_assignment(next_sid, wh_id, s_next):
                if assign_shipment(next_sid, wh_id, s_next):
                    return True

        # Backtrack
        del assignments[next_sid]
        # Restore state - this is complex, need to undo all changes
        # Actually, let's use a different approach with state snapshots

    # Simpler backtracking with state restoration
    def backtrack(idx):
        if idx == len(shipment_order):
            return True

        sid = shipment_order[idx]
        s = shipments[sid]

        for opt in shipment_static_options.get(sid, []):
            wh_id = opt["warehouse_id"]
            if is_valid_assignment(sid, wh_id, s):
                # Make assignment
                assignments[sid] = (wh_id, s["destination_id"])
                wh_volume_used[wh_id] += s["volume"]
                wh_weight_used[wh_id] += s["weight"]
                route_key = (wh_id, s["destination_id"])
                route_volume_used[route_key] += s["volume"]
                route_weight_used[route_key] += s["weight"]
                if s["requires_hazmat"]:
                    wh_has_hazmat[wh_id] = True
                if s["requires_refrigerated"]:
                    wh_has_refrigerated[wh_id] = True

                if backtrack(idx + 1):
                    return True

                # Undo assignment
                del assignments[sid]
                wh_volume_used[wh_id] -= s["volume"]
                wh_weight_used[wh_id] -= s["weight"]
                route_volume_used[route_key] -= s["volume"]
                route_weight_used[route_key] -= s["weight"]
                if s["requires_hazmat"]:
                    wh_has_hazmat[wh_id] = False
                if s["requires_refrigerated"]:
                    wh_has_refrigerated[wh_id] = False

        return False

    if backtrack(0):
        return assignments
    else:
        print("Backtracking failed to find solution!")
        return None

def main():
    input_dir = Path("/app/task_file/input_data")
    output_file = Path("/app/task_file/output_data/assignments.jsonl")

    shipments, warehouses, destinations, routes, routes_by_wh, routes_by_wh_dest, compatibility = load_data(input_dir)

    print(f"Loaded {len(shipments)} shipments, {len(warehouses)} warehouses, {len(destinations)} destinations")

    assignments = solve_with_backtracking(shipments, warehouses, destinations, routes_by_wh_dest, compatibility)

    if assignments is None:
        print("No solution found!")
        return

    # Generate output sorted by shipment_id
    output_lines = []
    for sid in sorted(assignments.keys()):
        wh_id, dest_id = assignments[sid]
        output_lines.append(json.dumps({
            "shipment_id": sid,
            "warehouse_id": wh_id,
            "destination_id": dest_id
        }))

    with open(output_file, 'w') as f:
        f.write('\n'.join(output_lines))

    print(f"Solution found: {len(assignments)} assignments")

if __name__ == "__main__":
    main()
